tasks.tests:
val = [0.30, 0.20, 0.15, 0.12, 0.11, 0.10, 0.095, 0.09, 0.088, 0.086, 0.084, 0.082, 0.083, 0.085, 0.087, 0.089, 0.090, 0.092, 0.094, 0.096]
same = {"loss": val, "val_loss": val}
falling = {"loss": [0.40 - 0.02 * i for i in range(20)], "val_loss": val}
assert best_epoch(same) == 12, "counts epochs from 1: the lowest loss at position 11 is epoch 12"
assert best_epoch(falling) == 12, "reads the validation loss, not the training loss that falls for all 20 epochs"

base = {"units": 128, "dropout": 0.0, "epochs": 20, "seed": 42, "val_rows": 6000}
with_dropout = {"units": 128, "dropout": 0.2, "epochs": 20, "seed": 42, "val_rows": 6000}
wider_and_dropout = {"units": 256, "dropout": 0.2, "epochs": 20, "seed": 42, "val_rows": 6000}
new_seed_too = {"units": 128, "dropout": 0.2, "epochs": 20, "seed": 7, "val_rows": 6000}
same_again = {"units": 128, "dropout": 0.0, "epochs": 20, "seed": 42, "val_rows": 6000}
assert the_one_change(base, with_dropout) == "dropout", "names the one setting that changed"
assert raises(ValueError, the_one_change, base, wider_and_dropout), "raises ValueError when the layer width and dropout changed together"
assert raises(ValueError, the_one_change, base, new_seed_too), "counts the seed: a new seed as well as new dropout raises ValueError"
assert raises(ValueError, the_one_change, base, same_again), "raises ValueError when nothing changed"
